package gal.rodrigosambade.locationlab; import android.content.*; import android.util.Log; import com.google.android.gms.location.*; public class ActivityTransitionReceiver extends BroadcastReceiver{public void onReceive(Context c,Intent i){if(!ActivityTransitionResult.hasResult(i))return;ActivityTransitionResult r=ActivityTransitionResult.extractResult(i);if(r!=null)for(ActivityTransitionEvent e:r.getTransitionEvents())Log.i("ActivityLab","activity="+e.getActivityType()+" transition="+e.getTransitionType());}}